files.content:
.dp-popover{
  position:fixed;
  inset:auto;
  margin:0;
}
.dp-wrap{
  position:relative;
}
.dp-popover{
  position:absolute;
  top:calc(100% + var(--s-1));
  left:0;
  width:280px;
  background:var(--obsidian-900);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-lg);
  box-shadow:var(--sh-3);
  padding:var(--s-3);
  z-index:var(--z-popover);
  font-family:var(--font-sans);
  opacity:0;
  transform:translateY(-4px);
  pointer-events:none;
  transition:opacity var(--d-quick) var(--ease-accel), transform var(--d-quick) var(--ease-accel);
}
.dp-popover[hidden]{
  display:none;
}
.dp-header{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:var(--s-1) var(--s-1) var(--s-2);
}
.dp-title{
  flex:1;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:var(--s-1);
  background:transparent;
  border:0;
  cursor:pointer;
  font-family:var(--font-sans);
  font-size:var(--t-small);
  font-weight:600;
  color:var(--obsidian-100);
  letter-spacing:var(--tr-snug);
  padding:var(--s-1) var(--s-2);
  border-radius:var(--r-sm);
  transition:background var(--d-quick) var(--ease-standard);
}
.dp-title:hover{
  background:var(--obsidian-800);
}
.dp-title:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--s-px);
  box-shadow:var(--ring-halo);
}
.dp-title svg{
  width:var(--icon-xs);
  height:var(--icon-xs);
  color:var(--obsidian-400);
  transition:transform var(--d-quick) var(--ease-standard);
}
.dp-popover[data-mode="years"] .dp-title svg{
  transform:rotate(180deg);
}
.dp-nav{
  display:grid;
  place-items:center;
  width:28px;
  height:28px;
  padding:0;
  border:0;
  background:transparent;
  cursor:pointer;
  color:var(--obsidian-300);
  border-radius:var(--r-sm);
  transition:color var(--d-quick) var(--ease-standard), background var(--d-quick) var(--ease-standard);
}
.dp-nav:hover:not(:disabled){
  color:var(--obsidian-100);
  background:var(--obsidian-800);
}
.dp-nav:disabled{
  color:var(--obsidian-500);
  cursor:not-allowed;
}
.dp-nav:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--s-px);
  box-shadow:var(--ring-halo);
}
.dp-nav svg{
  width:var(--icon-xs);
  height:var(--icon-xs);
}
.dp-dow{
  display:grid;
  grid-template-columns:repeat(7,1fr);
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-500);
  text-align:center;
  padding:var(--s-1) 0;
  margin-bottom:var(--s-0-5);
}
.dp-dow span{
  padding:var(--s-1) 0;
}
.dp-grid{
  display:grid;
  grid-template-columns:repeat(7,1fr);
  gap:var(--s-0-5);
}
.dp-day{
  display:grid;
  place-items:center;
  height:var(--s-8);
  padding:0;
  border:0;
  background:transparent;
  cursor:pointer;
  font-family:var(--font-sans);
  font-size:var(--t-small);
  font-variant-numeric:tabular-nums;
  color:var(--obsidian-100);
  border-radius:var(--r-sm);
  transition:background var(--d-quick) var(--ease-standard), color var(--d-quick) var(--ease-standard);
}
.dp-day:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:calc(-1 * var(--s-0-5));
  box-shadow:var(--ring-halo);
}
.dp-day:disabled{
  color:var(--obsidian-600);
  cursor:not-allowed;
  background:transparent;
}
.dp-popover.dp-range{
  width:580px;
}
.dp-range .dp-months{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:var(--s-5);
}
.dp-range .dp-month-title{
  text-align:center;
  font-family:var(--font-sans);
  font-size:var(--t-small);
  font-weight:600;
  color:var(--obsidian-100);
  padding:var(--s-1) 0 var(--s-2);
}
.dp-range .dp-presets{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:var(--s-1);
  padding:var(--s-2) 0 var(--s-1);
  margin-top:var(--s-2);
  border-top:var(--bw-1) solid var(--obsidian-800);
}
.dp-preset{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-300);
  background:transparent;
  border:0;
  cursor:pointer;
  padding:var(--s-2) var(--s-1);
  border-radius:var(--r-sm);
  transition:color var(--d-quick) var(--ease-standard), background var(--d-quick) var(--ease-standard);
}
.dp-preset:hover{
  color:var(--obsidian-100);
  background:var(--obsidian-800);
}
.dp-preset:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--s-px);
  box-shadow:var(--ring-halo);
}
@media (max-width:480px){
  .dp-popover.dp-range{
    width:280px;
  }
  .dp-range .dp-months{
    grid-template-columns:1fr;
    gap:var(--s-2);
  }
  .dp-range .dp-presets{
    grid-template-columns:repeat(2,1fr);
  }
}
.dp-year-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:var(--s-1);
  padding:var(--s-1) var(--s-0-5);
}
.dp-year{
  height:36px;
  display:grid;
  place-items:center;
  border:0;
  background:transparent;
  cursor:pointer;
  font-family:var(--font-sans);
  font-size:var(--t-small);
  color:var(--obsidian-100);
  border-radius:var(--r-sm);
  transition:background var(--d-quick) var(--ease-standard), color var(--d-quick) var(--ease-standard);
}
.dp-year:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:calc(-1 * var(--s-0-5));
  box-shadow:var(--ring-halo);
}
.dp-year:disabled{
  color:var(--obsidian-600);
  cursor:not-allowed;
}
.dp-footer{
  display:flex;
  justify-content:flex-end;
  margin-top:var(--s-1);
  padding:var(--s-1) 0 var(--s-0-5);
  border-top:var(--bw-1) solid var(--obsidian-800);
}
.dp-today-btn{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-300);
  background:transparent;
  border:0;
  cursor:pointer;
  padding:var(--s-1) var(--s-2);
  border-radius:var(--r-sm);
  transition:color var(--d-quick) var(--ease-standard), background var(--d-quick) var(--ease-standard);
}
.dp-today-btn:hover{
  color:var(--obsidian-100);
  background:var(--obsidian-800);
}
.dp-today-btn:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--s-px);
  box-shadow:var(--ring-halo);
}
@media (prefers-reduced-motion: reduce){
  .dp-popover, .dp-day, .dp-year, .dp-nav, .dp-title, .dp-today-btn{
    transition:none;
  }
}
.dp-popover)[hidden]{
  display:block;
}
.dp-popover){
  position:static;
  margin-top:var(--s-6);
  max-height:none;
  opacity:1;
  transform:none;
  pointer-events:auto;
}
